/* --- Prerequisites: a click (or Enter, Space) on a step lights its commands and dims the others --- */
(function(){
  var box = $id("pq"); if (!box) return;
  function pick(n){
    box.querySelectorAll(".pq-step").forEach(function(s){ var on = s.dataset.step === n; s.classList.toggle("on", on); s.setAttribute("aria-pressed", on); });
    box.querySelectorAll(".pq-cmd").forEach(function(c){ c.classList.toggle("off", c.dataset.step !== n); c.classList.toggle("lit", c.dataset.step === n); });
  }
  box.querySelectorAll(".pq-step").forEach(function(s){
    s.addEventListener("click", function(e){ if (e.target.closest("a")) return; pick(s.dataset.step); });
    s.addEventListener("keydown", function(e){ if (e.key === "Enter" || e.key === " "){ e.preventDefault(); e.stopPropagation(); pick(s.dataset.step); } });
  });
  onReset(box, function(){ pick("1"); });   /* step 1 lit, as first shown */
})();


