    var DL = {}; [["v", "v"], ["w", "\\omega"], ["vL", "v_L"], ["vR", "v_R"], ["R", "R"], ["x", "x"], ["y", "y"], ["th", "\\theta"], ["qz", "z"], ["qw", "w"]]
      .forEach(function(k){ DL[k[0]] = window.katex ? katex.renderToString(k[1], {throwOnError:false}) : k[1]; });
