    for (var gy = 0.5; gy < AH; gy += 0.5){ var c = P(0, gy), d = P(AW, gy); el(sv, "line", {x1:c[0], y1:c[1], x2:d[0], y2:d[1], stroke:C.grid, "stroke-width":1}); }
