    var arL = el(botG, "line", {stroke:C.live, "stroke-width":5, "stroke-linecap":"round"}), arR = el(botG, "line", {stroke:C.live, "stroke-width":5, "stroke-linecap":"round"});
    var hdL = el(botG, "path", {fill:C.live}), hdR = el(botG, "path", {fill:C.live});
